  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

:root {
  /* Boldteq light theme — primary site theme */
  --background: oklch(1 0 0);
  --foreground: oklch(0.22 0.05 255);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.22 0.05 255);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.22 0.05 255);
  --primary: oklch(0.22 0.05 255);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.97 0.005 210);
  --secondary-foreground: oklch(0.22 0.05 255);
  --muted: oklch(0.97 0.005 210);
  --muted-foreground: oklch(0.5 0.02 255);
  --accent: oklch(0.78 0.14 210);
  --accent-foreground: oklch(0.22 0.05 255);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.92 0.005 210);
  --input: oklch(0.92 0.005 210);
  --ring: oklch(0.78 0.14 210);
  --chart-1: oklch(0.78 0.14 210);
  --chart-2: oklch(0.55 0.18 240);
  --chart-3: oklch(0.94 0.08 95);
  --chart-4: oklch(0.22 0.05 255);
  --chart-5: oklch(0.5 0.02 255);
  --radius: 0.625rem;
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.22 0.05 255);
  --sidebar-primary: oklch(0.22 0.05 255);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0.005 210);
  --sidebar-accent-foreground: oklch(0.22 0.05 255);
  --sidebar-border: oklch(0.92 0.005 210);
  --sidebar-ring: oklch(0.78 0.14 210);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  html {
    @apply font-sans scroll-smooth;
  }
}

@layer utilities {
  .gradient-cyan {
    background: linear-gradient(135deg, oklch(0.78 0.14 210), oklch(0.55 0.18 240));
  }
  .gradient-cyan-text {
    background: linear-gradient(135deg, oklch(0.78 0.14 210), oklch(0.55 0.18 240));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  .bg-navy {
    background-color: oklch(0.22 0.05 255);
  }
  .bg-navy-deep {
    background-color: oklch(0.24 0.06 255);
  }
}

