"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Send, CheckCircle } from "lucide-react";

export function NewsletterSignup({
  variant = "light",
}: {
  variant?: "light" | "dark";
}) {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!email) return;
    // TODO: integrate with email service
    setStatus("success");
    setEmail("");
  }

  const isDark = variant === "dark";

  return (
    <div className="text-center">
      <h3
        className={cn(
          "text-2xl font-bold sm:text-3xl",
          isDark ? "text-white" : "text-foreground"
        )}
      >
        Join 500+ Subscribers
      </h3>
      <p
        className={cn(
          "mt-2 text-sm font-medium",
          isDark ? "text-brand-cyan" : "gradient-cyan-text"
        )}
      >
        Agency Growth Insights Delivered Monthly
      </p>
      <p
        className={cn(
          "mx-auto mt-3 max-w-md text-sm",
          isDark ? "text-white/60" : "text-muted-foreground"
        )}
      >
        Smart growth strategies, CRM playbooks, industry trends, early product
        updates, and member-only offers — designed for modern agencies.
      </p>

      {status === "success" ? (
        <div className="mt-6 flex items-center justify-center gap-2 text-emerald-400">
          <CheckCircle className="h-5 w-5" />
          <span className="text-sm font-medium">
            Thank you! Your submission has been received!
          </span>
        </div>
      ) : (
        <form
          onSubmit={handleSubmit}
          className="mx-auto mt-6 flex max-w-md gap-2"
        >
          <Input
            type="email"
            placeholder="Enter your email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            className={cn(
              "flex-1",
              isDark &&
                "border-white/20 bg-white/10 text-white placeholder:text-white/40"
            )}
          />
          <Button type="submit" className="gradient-cyan border-0 text-white">
            <Send className="mr-2 h-4 w-4" />
            Subscribe
          </Button>
        </form>
      )}

      <p
        className={cn(
          "mt-3 text-xs",
          isDark ? "text-white/40" : "text-muted-foreground"
        )}
      >
        100% privacy guaranteed. Unsubscribe anytime.
      </p>
    </div>
  );
}

