  --radius-4xl: calc(var(--radius) * 2.6);
}

:root {
  /* Webflow design tokens */
  --blue: #082753;
  --white: white;
  --black: black;
  --para-small: 16px;
  --h2: 40px;
  --h1: 3.125rem;
  --para: 1.125rem;
  --h3: 1.53rem;
  --button-text: 1rem;

  /* shadcn semantic colors mapped to Boldteq */
  --background: #fff;
  --foreground: #111827;
  --card: #fff;
  --card-foreground: #111827;
  --popover: #fff;
  --popover-foreground: #111827;
  --primary: #082753;
  --primary-foreground: #fff;
  --secondary: #f5f7fa;
  --secondary-foreground: #111827;
  --muted: #f7f7f8;
  --muted-foreground: #6b7280;
  --accent: #21cfff;
  --accent-foreground: #082753;
