  --border: #e5e7eb;
  --input: #e5e7eb;
  --ring: #21cfff;
  --chart-1: #21cfff;
  --chart-2: #019ae6;
  --chart-3: #FFEB85;
  --chart-4: #082753;
  --chart-5: #6b7280;
  --radius: 0.625rem;
  --sidebar: #fafafa;
  --sidebar-foreground: #111827;
  --sidebar-primary: #082753;
  --sidebar-primary-foreground: #fff;
  --sidebar-accent: #f5f7fa;
  --sidebar-accent-foreground: #111827;
  --sidebar-border: #e5e7eb;
  --sidebar-ring: #21cfff;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-roobert), system-ui, -apple-system, sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
  html {
    @apply scroll-smooth;
  }
}

@layer utilities {
  .gradient-cyan {
    background: linear-gradient(90deg, #21cfff, #019ae6);
  }
  .gradient-cyan-text {
    background: linear-gradient(90deg, #21cfff, #019ae6);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  .bg-navy {
    background-color: #092245;
  }
  .bg-navy-deep {
    background-color: #082753;
  }

  /* Webflow section spacing */
  .section-large {
    padding: 128px 5%;
  }
  .section-regular {
    padding: 64px 5%;
  }

  /* Card hover from Webflow */
  .card-hover {
    transition: background-color 0.3s, border-color 0.4s, box-shadow 0.3s;
  }
  .card-hover:hover {
    background-color: #cdebfa;
    border-color: #009ce0;
  }

  /* Shimmer animation */
  @keyframes shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
  }
  .animate-shimmer {
    background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    animation: shimmer 1.5s ease-in-out infinite;
  }
}

