import type { Metadata } from "next";
import localFont from "next/font/local";
import Script from "next/script";
import { Navbar } from "@/components/layout/navbar";
import { Footer } from "@/components/layout/footer";
import { PostHogProvider } from "@/lib/analytics/posthog-provider";
import { SITE_CONFIG } from "@/lib/constants/site";
import "./globals.css";

const roobertPro = localFont({
  src: [
    {
      path: "../../public/fonts/RoobertPRO-Light.woff2",
      weight: "300",
      style: "normal",
    },
    {
      path: "../../public/fonts/RoobertPRO-Regular.woff2",
      weight: "400",
      style: "normal",
    },
    {
      path: "../../public/fonts/RoobertPRO-Medium.woff2",
      weight: "500",
      style: "normal",
    },
    {
      path: "../../public/fonts/RoobertPRO-Bold.woff2",
      weight: "700",
      style: "normal",
    },
  ],
  variable: "--font-roobert",
  display: "swap",
});

export const metadata: Metadata = {
  title: {
    default: "White Label Web Design & Development Services | Boldteq",
    template: "%s | Boldteq",
  },
  description: SITE_CONFIG.description,
  metadataBase: new URL(SITE_CONFIG.url),
  verification: {
    google: "JlE0J7GQIyTbyMqTli7Z0EOoLHC08lyX-cdkTY9iRLI",
  },
  openGraph: {
    type: "website",
    siteName: SITE_CONFIG.name,
    locale: "en_US",
  },
  twitter: {
    card: "summary_large_image",
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" className={`${roobertPro.variable} h-full antialiased`}>
      <body className="flex min-h-full flex-col font-roobert">
        <PostHogProvider>
          <Navbar />
          <main className="flex-1">{children}</main>
          <Footer />
        </PostHogProvider>

        {/* Chatwoot */}
        {process.env.NEXT_PUBLIC_CHATWOOT_TOKEN && (
          <Script
            id="chatwoot-sdk"
            strategy="afterInteractive"
            dangerouslySetInnerHTML={{
              __html: `
                (function(d,t) {
                  var BASE_URL="https://app.chatwoot.com";
                  var g=d.createElement(t),s=d.getElementsByTagName(t)[0];
                  g.src=BASE_URL+"/packs/js/sdk.js";
                  g.defer = true;
                  g.async = true;
                  s.parentNode.insertBefore(g,s);
                  g.onload=function(){
                    window.chatwootSDK.run({
                      websiteToken: '${process.env.NEXT_PUBLIC_CHATWOOT_TOKEN}',
                      baseUrl: BASE_URL
                    })
                  }
                })(document,"script");
              `,
            }}
          />
        )}
      </body>
    </html>
  );
}

