import { chromium } from "@playwright/test";

async function audit() {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();

  // Collect console errors
  const consoleErrors = [];
  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });

  await page.goto("http://localhost:3000", { waitUntil: "networkidle", timeout: 30000 });

  // Screenshot full page
  await page.screenshot({ path: "tests/screenshots/local-full.png", fullPage: true });
  // Screenshot hero
  await page.evaluate(() => window.scrollTo(0, 0));
  await new Promise(r => setTimeout(r, 500));
  await page.screenshot({ path: "tests/screenshots/local-hero.png" });

  // Audit computed styles
  const results = await page.evaluate(() => {
    const out = {};

    function grab(selector, label) {
      const el = document.querySelector(selector);
      if (!el) { out[label] = { error: "NOT FOUND" }; return; }
      const cs = window.getComputedStyle(el);
      out[label] = {
        fontFamily: cs.fontFamily.substring(0, 50),
        fontSize: cs.fontSize,
        fontWeight: cs.fontWeight,
        lineHeight: cs.lineHeight,
        color: cs.color,
        bgColor: cs.backgroundColor,
        padding: cs.padding,
        borderRadius: cs.borderRadius,
      };
    }

    grab("body", "body");
    grab("header", "header");
    grab("nav", "nav");
    grab("h1", "h1");
    grab("h2", "h2");
    grab("footer", "footer");

    // Count all sections
    const secs = document.querySelectorAll("section");
    out.sectionCount = secs.length;

    // Check all h2s
    const h2s = document.querySelectorAll("h2");
    out.h2Count = h2s.length;
    const h2Data = [];
    h2s.forEach((h, i) => {
      if (i < 12) {
        const cs = window.getComputedStyle(h);
        h2Data.push({
          text: h.textContent.trim().substring(0, 40),
          size: cs.fontSize,
          weight: cs.fontWeight,
          lh: cs.lineHeight,
          color: cs.color,
        });
      }
    });
    out.h2Styles = h2Data;

    // Check nav links
    const navLinks = document.querySelectorAll("nav a");
    out.navLinkCount = navLinks.length;

    // Check images
    const imgs = document.querySelectorAll("img");
    const brokenImgs = [];
    imgs.forEach(img => {
      if (!img.complete || img.naturalWidth === 0) {
        brokenImgs.push(img.src);
      }
    });
    out.totalImages = imgs.length;
    out.brokenImages = brokenImgs;

    // Check buttons with gradient
    const allEls = document.querySelectorAll("a, button");
    const gradientBtns = [];
    allEls.forEach(el => {
      const cs = window.getComputedStyle(el);
      if (cs.backgroundImage.includes("gradient")) {
        gradientBtns.push({
          text: el.textContent.trim().substring(0, 30),
          bg: cs.backgroundImage.substring(0, 80),
          radius: cs.borderRadius,
          padding: cs.padding,
          fontSize: cs.fontSize,
        });
      }
    });
    out.gradientButtons = gradientBtns;

    return out;
  });

  console.log(JSON.stringify(results, null, 2));

  if (consoleErrors.length > 0) {
    console.log("\n=== CONSOLE ERRORS ===");
    consoleErrors.forEach(e => console.log("  " + e));
  } else {
    console.log("\n=== NO CONSOLE ERRORS ===");
  }

  await browser.close();
}

audit().catch(console.error);

